    ('TENUA', 'porta persiana tenua 4 ante', 'BM_TENB04', 2500, 2100, 2495.0000, 911.9625),
    ('TENUA', 'porta persiana tenua 4 ante', 'BM_TENB04', 2500, 2200, 2576.0000, 940.9200),
    ('TENUA', 'porta persiana tenua 4 ante', 'BM_TENB04', 2500, 2300, 2657.0000, 969.8775),
    ('TENUA', 'porta persiana tenua 4 ante', 'BM_TENB04', 2500, 2400, 2737.0000, 998.4775),
    ('TENUA', 'porta persiana tenua 4 ante', 'BM_TENB04', 2500, 2500, 2818.0000, 1027.4350),
    ('TENUA', 'porta persiana tenua 4 ante', 'BM_TENB04', 2500, 2600, 2898.0000, 1056.0350),
    ('TENUA', 'porta persiana tenua 4 ante', 'BM_TENB04', 2500, 2700, 2978.0000, 1084.6350),
    ('TENUA', 'porta persiana tenua 4 ante', 'BM_TENB04', 2500, 2800, 3059.0000, 1113.5925),
    ('TENUA', 'porta persiana tenua 4 ante', 'BM_TENB04', 2500, 2900, 3140.0000, 1142.5500),
    ('TENUA', 'porta persiana tenua 4 ante', 'BM_TENB04', 2500, 3000, 3221.0000, 1171.5075);

  SELECT count(*) INTO v_input_count FROM _ke_bei_persiane_import;
  IF v_input_count <> 11648 THEN
    RAISE EXCEPTION 'Persiane import expected 11648 rows, got %', v_input_count;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM _ke_bei_persiane_import
    GROUP BY series_name, category_name, tip_code, width_mm, height_mm
    HAVING count(*) > 1
  ) THEN
    RAISE EXCEPTION 'Persiane import contains duplicate dimensions for the same family.';
  END IF;

  -- 1) Macrocategorie: one per NomeSerie.
  WITH macros AS (
    SELECT
      series_name,
      dense_rank() OVER (ORDER BY series_name) * 10 + 2000 AS sort_order,
      count(*) AS rows_count,
      count(DISTINCT category_name || '|' || tip_code) AS family_count
    FROM _ke_bei_persiane_import
    GROUP BY series_name
  )
  INSERT INTO public.listino_macrocategorie (
    company_id, nome, descrizione, icona, colore, sort_order, attivo
  )
  SELECT
    v_company_id,
    series_name,
    concat('Persiane — serie ', series_name, '. Import PERSIANE.xlsx: ', family_count, ' famiglie, ', rows_count, ' misure. Prezzi imponibili: acquisto netto da sconto fornitore, vendita +100%.'),
    'Blinds',
    '#f97316',
    sort_order,
    true
  FROM macros
  ON CONFLICT (company_id, nome) DO UPDATE
    SET descrizione = EXCLUDED.descrizione,
        icona = EXCLUDED.icona,
        colore = EXCLUDED.colore,
        sort_order = EXCLUDED.sort_order,
        attivo = true,
        updated_at = now();

  -- 2) Categorie/famiglie: one per NomeSerie + DescrizTip + Tip.
  WITH families AS (
    SELECT
      i.series_name,
      i.category_name,
      i.tip_code,
      concat(i.series_name, ' — ', i.category_name) AS category_full_name,
      min(i.purchase_net) AS min_purchase_net,
      min(i.purchase_net * 2) AS min_sale_net,
      count(*) AS rows_count,
      min(i.width_mm) AS min_width,
      max(i.width_mm) AS max_width,
      min(i.height_mm) AS min_height,
      max(i.height_mm) AS max_height,
      dense_rank() OVER (ORDER BY i.series_name, i.category_name, i.tip_code) * 10 + 2000 AS sort_order
    FROM _ke_bei_persiane_import i
    GROUP BY i.series_name, i.category_name, i.tip_code
  ), cats AS (
    INSERT INTO public.listino_categorie (
      company_id,
      macrocategoria_id,
      nome,
      descrizione,
      colore,
      icona,
      sort_order
    )
    SELECT
      v_company_id,
      lm.id,
      f.category_full_name,
      concat('Persiane ', f.series_name, ' — ', f.category_name, '. Codice fornitore ', f.tip_code, '. Griglia ', f.rows_count, ' misure (L ', f.min_width, '-', f.max_width, ' mm / H ', f.min_height, '-', f.max_height, ' mm).'),
      '#f97316',
      'PanelTop',
      f.sort_order
    FROM families f
    JOIN public.listino_macrocategorie lm
      ON lm.company_id = v_company_id
     AND lm.nome = f.series_name
    ON CONFLICT (company_id, nome) DO UPDATE
      SET macrocategoria_id = EXCLUDED.macrocategoria_id,
          descrizione = EXCLUDED.descrizione,
          colore = EXCLUDED.colore,
          icona = EXCLUDED.icona,
          sort_order = EXCLUDED.sort_order,
          updated_at = now()
    RETURNING id
  )
  SELECT count(*) INTO v_family_count FROM families;

  -- Insert missing article_families. Existing active families are updated below.
  WITH families AS (
    SELECT
      i.series_name,
      i.category_name,
      i.tip_code,
      concat(i.series_name, ' — ', i.category_name) AS family_name,
      min(i.purchase_net) AS min_purchase_net,
      min(i.purchase_net * 2) AS min_sale_net,
      count(*) AS rows_count,
      dense_rank() OVER (ORDER BY i.series_name, i.category_name, i.tip_code) * 10 + 2000 AS sort_order
    FROM _ke_bei_persiane_import i
    GROUP BY i.series_name, i.category_name, i.tip_code
  )
  INSERT INTO public.article_families (
    company_id,
    vertical,
    categoria_id,
    nome,
    descrizione,
    modalita_prezzo_base,
    prezzo_base_mode,
    markup_tipo,
    markup_valore,
    prezzo_base_acquisto,
    prezzo_base_vendita,
    vat_rate,
    vat_rate_acquisto,
    unit_of_measure,
    griglia_asse_x_label,
    griglia_asse_y_label,
    griglia_unita,
    manodopera_modalita,
    manodopera_unita,
    custom_field_values,
    sort_order,
    attivo
  )
  SELECT
    v_company_id,
    'serramentista',
    lc.id,
    f.family_name,
    concat('Persiane ', f.series_name, ' — ', f.category_name, '. Codice fornitore ', f.tip_code, '. Prezzi imponibili: acquisto = Scontato con Coprifili; vendita = acquisto x2; IVA acquisto 22%; IVA vendita 10%.'),
    'griglia',
    'acquisto_markup',
    'percentuale',
    100,
    round(f.min_purchase_net, 4),
    round(f.min_sale_net, 4),
    10,
    22,
    'pz',
    'Larghezza (mm)',
    'Altezza (mm)',
    'mm',
    'nessuna',
    'pz',
    jsonb_build_object(
      'source', 'PERSIANE.xlsx',
      'nome_serie', f.series_name,
      'descrizione_tipologia', f.category_name,
      'tip_code', f.tip_code,
      'pricing_rule', 'purchase_net = Scontato con Coprifili; sale_net = purchase_net * 2; vat_purchase = 22; vat_sale = 10',
      'rows_count', f.rows_count
    ),
    f.sort_order,
    true
  FROM families f
  JOIN public.listino_categorie lc
    ON lc.company_id = v_company_id
   AND lc.nome = f.family_name
  WHERE NOT EXISTS (
    SELECT 1
    FROM public.article_families existing
    WHERE existing.company_id = v_company_id
      AND existing.vertical = 'serramentista'
      AND existing.nome = f.family_name
      AND existing.deleted_at IS NULL
  );

  -- Update all active article families so reruns repair existing data too.
  WITH families AS (
    SELECT
      i.series_name,
      i.category_name,
      i.tip_code,
      concat(i.series_name, ' — ', i.category_name) AS family_name,
      min(i.purchase_net) AS min_purchase_net,
      min(i.purchase_net * 2) AS min_sale_net,
      count(*) AS rows_count,
      min(i.width_mm) AS min_width,
      max(i.width_mm) AS max_width,
      min(i.height_mm) AS min_height,
      max(i.height_mm) AS max_height,
      dense_rank() OVER (ORDER BY i.series_name, i.category_name, i.tip_code) * 10 + 2000 AS sort_order
    FROM _ke_bei_persiane_import i
    GROUP BY i.series_name, i.category_name, i.tip_code
  )
  UPDATE public.article_families af
     SET categoria_id = lc.id,
         descrizione = concat('Persiane ', f.series_name, ' — ', f.category_name, '. Codice fornitore ', f.tip_code, '. Griglia ', f.rows_count, ' misure (L ', f.min_width, '-', f.max_width, ' mm / H ', f.min_height, '-', f.max_height, ' mm). Prezzi imponibili: acquisto = Scontato con Coprifili; vendita = acquisto x2; IVA acquisto 22%; IVA vendita 10%.'),
         modalita_prezzo_base = 'griglia',
         prezzo_base_mode = 'acquisto_markup',
         markup_tipo = 'percentuale',
         markup_valore = 100,
         sconto_fornitore_1 = 0,
         sconto_fornitore_2 = 0,
         prezzo_base_acquisto = round(f.min_purchase_net, 4),
         prezzo_base_vendita = round(f.min_sale_net, 4),
         vat_rate = 10,
         vat_rate_acquisto = 22,
         unit_of_measure = 'pz',
         griglia_asse_x_label = 'Larghezza (mm)',
         griglia_asse_y_label = 'Altezza (mm)',
         griglia_unita = 'mm',
         manodopera_modalita = 'nessuna',
         manodopera_unita = 'pz',
         custom_field_values = COALESCE(af.custom_field_values, '{}'::jsonb) || jsonb_build_object(
           'source', 'PERSIANE.xlsx',
           'nome_serie', f.series_name,
           'descrizione_tipologia', f.category_name,
           'tip_code', f.tip_code,
           'pricing_rule', 'purchase_net = Scontato con Coprifili; sale_net = purchase_net * 2; vat_purchase = 22; vat_sale = 10',
           'rows_count', f.rows_count
         ),
         sort_order = f.sort_order,
         attivo = true,
         updated_at = now()
    FROM families f
    JOIN public.listino_categorie lc
      ON lc.company_id = v_company_id
     AND lc.nome = f.family_name
   WHERE af.company_id = v_company_id
     AND af.vertical = 'serramentista'
     AND af.nome = f.family_name
     AND af.deleted_at IS NULL;

  SELECT count(DISTINCT af.id)
    INTO v_family_count
  FROM _ke_bei_persiane_import i
  JOIN public.article_families af
    ON af.company_id = v_company_id
   AND af.vertical = 'serramentista'
   AND af.nome = concat(i.series_name, ' — ', i.category_name)
   AND af.deleted_at IS NULL;

  IF v_family_count <> 92 THEN
    RAISE EXCEPTION 'Persiane import expected 92 active families, found %', v_family_count;
  END IF;

  -- Replace imported grid cells for these families, preserving unrelated listino content.
  DELETE FROM public.listino_griglia lg
  USING public.article_families af
  WHERE lg.company_id = v_company_id
    AND lg.family_id = af.id
    AND af.company_id = v_company_id
    AND af.vertical = 'serramentista'
    AND af.deleted_at IS NULL
    AND COALESCE(af.custom_field_values->>'source', '') = 'PERSIANE.xlsx';

  INSERT INTO public.listino_griglia (
    company_id,
    family_id,
    valore_x,
    valore_y,
    prezzo_acquisto,
    prezzo_vendita,
    note
  )
  SELECT
    v_company_id,
    af.id,
    i.width_mm,
    i.height_mm,
    round(i.purchase_net, 4),
    round(i.purchase_net * 2, 4),
    concat(
      i.tip_code,
      ' | NomeSerie=', i.series_name,
      ' | CostoFin fornitore imponibile=', round(i.supplier_total_net, 4),
      ' | acquisto_scontato_con_coprifili_imponibile=', round(i.purchase_net, 4),
      ' | vendita_imponibile_markup_100=', round(i.purchase_net * 2, 4),
      ' | iva_acquisto=22 | iva_vendita=10'
    )
  FROM _ke_bei_persiane_import i
  JOIN public.article_families af
    ON af.company_id = v_company_id
   AND af.vertical = 'serramentista'
   AND af.nome = concat(i.series_name, ' — ', i.category_name)
   AND af.deleted_at IS NULL;

  GET DIAGNOSTICS v_grid_count = ROW_COUNT;
  IF v_grid_count <> v_input_count THEN
    RAISE EXCEPTION 'Persiane import expected to insert % grid cells, inserted %', v_input_count, v_grid_count;
  END IF;

  SELECT count(DISTINCT lm.id)
    INTO v_macro_count
  FROM public.listino_macrocategorie lm
  WHERE lm.company_id = v_company_id
    AND lm.nome IN (SELECT DISTINCT series_name FROM _ke_bei_persiane_import);

  IF v_macro_count <> 12 THEN
    RAISE EXCEPTION 'Persiane import expected 12 macrocategories, found %', v_macro_count;
  END IF;

  RAISE NOTICE 'Ke Bei persiane import completed: % macrocategories, % families, % grid cells.', v_macro_count, v_family_count, v_grid_count;
END $$;
